import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.servlet.http.HttpServletRequest;

public class FixedFileAccess {
    public String readFile(HttpServletRequest request) {
        String filename = request.getParameter("file");

        // Validate that the filename does not contain null bytes or path traversal sequences
        if (filename == null || filename.contains("..") || filename.contains("/") || filename.contains("\\")) {
            throw new IllegalArgumentException("Invalid file name");
        }

        // Construct the base directory and the target file path securely
        Path basePath = Paths.get("/var/www/uploads").toAbsolutePath().normalize();
        Path targetPath = basePath.resolve(filename).normalize();

        // Ensure the resolved path is still within the base directory
        if (!targetPath.startsWith(basePath)) {
            throw new SecurityException("Access denied: Attempted path traversal detected");
        }

        File file = targetPath.toFile();

        if (file.exists() && file.canRead()) {
            return "File found";
        }
        return "File not found";
    }
}
